import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not parameters:
        raise Exception("URL and parameters must be non‑empty.")
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
    except requests.RequestException as e:
        raise Exception(f"Failed to access URL: {e}")
    try:
        data = response.json()
    except json.JSONDecodeError:
        raise Exception("Invalid JSON data received.")
    if not data:
        raise Exception("Empty data received.")
    df = pd.DataFrame(data)
    if df.empty:
        raise Exception("DataFrame is empty.")
    numeric_df = df.select_dtypes(include=['number'])
    if numeric_df.empty:
        raise Exception("No numerical data for correlation.")
    corr = numeric_df.corr()
    fig, ax = plt.subplots()
    sns.heatmap(corr, annot=True, fmt=".2f", ax=ax)
    ax.set_title("Correlation Heatmap")
    return df, ax
